# Required per environment / user.
# No defaults intentionally.
: "${VPN_SERVER_IP:=}"
: "${VPN_USERNAME:=}"
: "${VPN_CHECK_HOST_IP:=}"

# VPN implementation defaults.
# Preconfigured for the currently verified L2TP/IPsec VPN server.
VPN_CONNECTION_NAME="${VPN_CONNECTION_NAME:-l2tp-vpn}"

VPN_IKE_VERSION="${VPN_IKE_VERSION:-ikev1}"
VPN_IKE_PROPOSAL="${VPN_IKE_PROPOSAL:-3des-sha1-modp1024!}"
VPN_ESP_PROPOSAL="${VPN_ESP_PROPOSAL:-aes256-sha1!}"
VPN_IKE_LIFETIME="${VPN_IKE_LIFETIME:-8h}"

VPN_L2TP_PORT="${VPN_L2TP_PORT:-1701}"

VPN_PPP_MTU="${VPN_PPP_MTU:-1280}"
VPN_PPP_MRU="${VPN_PPP_MRU:-1280}"
VPN_PPP_INTERFACE="${VPN_PPP_INTERFACE:-ppp0}"

# Operational defaults.
VPN_IPSEC_START_DELAY_SEC="${VPN_IPSEC_START_DELAY_SEC:-1}"
VPN_L2TP_START_DELAY_SEC="${VPN_L2TP_START_DELAY_SEC:-1}"
VPN_CONNECT_TIMEOUT_SEC="${VPN_CONNECT_TIMEOUT_SEC:-20}"
VPN_PING_TIMEOUT_SEC="${VPN_PING_TIMEOUT_SEC:-20}"
VPN_DISCONNECT_TIMEOUT_SEC="${VPN_DISCONNECT_TIMEOUT_SEC:-5}"
